"use client";

import {
  clearPendingFeatureTourStep,
  profileFeatureTourConfig,
  setPendingFeatureTourStep,
  type FeatureTourStep,
} from "@/lib/featureTour";

export type HelpTopic = {
  id: string;
  title: string;
  description: string;
  route: string;
  step: FeatureTourStep;
};

export const helpTopics: HelpTopic[] = [
  {
    id: "edit-profile",
    title: "Edit Profile",
    description: "Lihat cara mengubah data profil langsung dari halaman profile.",
    route: "/profile",
    step: "edit",
  },
  {
    id: "change-photo",
    title: "Ganti Foto Profil",
    description: "Pelajari langkah memilih dan mengganti foto profil.",
    route: "/profile",
    step: "photo",
  },
  {
    id: "reset-password",
    title: "Reset Password",
    description: "Jalankan tour untuk melihat alur ubah password dari profile.",
    route: "/profile",
    step: "password",
  },
];

type HelpRouter = {
  push: (href: string) => void;
};

export function launchHelpTopic(
  router: HelpRouter,
  topic: HelpTopic,
) {
  clearPendingFeatureTourStep(profileFeatureTourConfig);
  setPendingFeatureTourStep(profileFeatureTourConfig, topic.step);
  router.push(topic.route);
}
